1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the telephone on a create request to E.164 form (see {@link TelephoneNormalizer}).
9	 * Stores the E.164 value back on the request (mutating the shared {@code @Val} object) so
10	 * {@link BuildOwner} and the response carry it; rejects with {@link InvalidTelephoneException}
11	 * (400) when the number cannot form valid E.164. Runs after {@link ValidateNewOwner} has
12	 * confirmed the field is present.
13	 */
14	public class NormalizeOwnerTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
17	        String raw = request.getTelephone();
18	        String e164 = TelephoneNormalizer.toE164(raw);
19	        if (e164 == null) {
20	            throw new InvalidTelephoneException(raw);
21	        }
22	        request.setTelephone(e164);
23	    }
24	}
