3	/**
4	 * Thrown when a create-owner request carries a telephone that cannot be normalized to a
5	 * valid E.164 number (a '+' followed by 8 to 15 digits). Handled by
6	 * {@link InvalidTelephoneExceptionHandler}, which responds 400 with the rejected value.
7	 */
8	public class InvalidTelephoneException extends Exception {
9	
10	    private final String rejectedValue;
11	
12	    public InvalidTelephoneException(String rejectedValue) {
13	        super("Telephone cannot be normalized to a valid E.164 number: " + rejectedValue);
14	        this.rejectedValue = rejectedValue;
15	    }
16	
17	    public String getRejectedValue() {
18	        return this.rejectedValue;
19	    }
20	}
